    (p_target_company_id, 'Profit and Loss Statement', 'Detailed profit and loss statements for the review period', 'Financial', 1, 'high', true, 'outstanding', 'not_started'),
    (p_target_company_id, 'Balance Sheet', 'Current balance sheet showing assets, liabilities, and equity', 'Financial', 1, 'high', true, 'outstanding', 'not_started'),
