    (p_target_company_id, 'Staff Matrix', 'Staff matrix showing organizational structure (can be anonymized)', 'HR', 1, 'medium', true, 'outstanding', 'not_started'),
    
    -- Stage 2: Post-heads-of-terms Requirements (23 requirements)
    (p_target_company_id, 'Audited Financial Statements (3 Years)', 'Complete audited financial statements for the last three fiscal years', 'Financial', 2, 'high', true, 'outstanding', 'not_started'),
