    (p_target_company_id, 'Employment Agreements & HR Policies', 'Key employee agreements, HR policies, and compensation structures', 'HR', 2, 'medium', true, 'outstanding', 'not_started'),
    (p_target_company_id, 'Intellectual Property Documentation', 'Patents, trademarks, copyrights, and IP assignment agreements', 'Legal', 2, 'high', false, 'outstanding', 'not_started'),
    (p_target_company_id, 'Regulatory Licenses & Permits', 'All required regulatory licenses, permits, and compliance certificates', 'Regulatory', 2, 'high', true, 'outstanding', 'not_started'),
    (p_target_company_id, 'Environmental & Safety Compliance', 'Environmental assessments and workplace safety compliance records', 'Regulatory', 2, 'medium', false, 'outstanding', 'not_started'),
    (p_target_company_id, 'IT Systems & Data Security', 'IT infrastructure overview, data security policies, and cyber security assessments', 'Technology', 2, 'medium', true, 'outstanding', 'not_started'),
    (p_target_company_id, 'Customer Analysis & Concentration', 'Detailed customer analysis including concentration and retention metrics', 'Commercial', 2, 'high', true, 'outstanding', 'not_started'),
    (p_target_company_id, 'Supplier Analysis & Dependencies', 'Key supplier relationships and dependency analysis', 'Commercial', 2, 'medium', true, 'outstanding', 'not_started'),
