--
-- Name: activity_summary; Type: VIEW; Schema: public; Owner: neondb_owner
--

CREATE VIEW public.activity_summary AS
 SELECT a.user_id,
    tc.user_company_id,
    a.activity_type,
    date_trunc('month'::text, a.activity_date) AS activity_month,
    count(*) AS activity_count,
    COALESCE(avg(a.duration_minutes), (0)::numeric) AS avg_duration,
    count(DISTINCT a.target_company_id) AS companies_contacted
   FROM (public.activities a
     JOIN public.target_companies tc ON ((a.target_company_id = tc.id)))
  WHERE (a.activity_date IS NOT NULL)
  GROUP BY a.user_id, tc.user_company_id, a.activity_type, (date_trunc('month'::text, a.activity_date));


