--
-- Name: deal_progression; Type: VIEW; Schema: public; Owner: neondb_owner
--

CREATE VIEW public.deal_progression AS
 SELECT sh.target_company_id,
    tc.user_company_id,
    sh.from_stage,
    sh.to_stage,
    sh.changed_at,
    lag(sh.changed_at) OVER (PARTITION BY sh.target_company_id ORDER BY sh.changed_at) AS previous_change,
    COALESCE(EXTRACT(days FROM (sh.changed_at - lag(sh.changed_at) OVER (PARTITION BY sh.target_company_id ORDER BY sh.changed_at))), (0)::numeric) AS days_in_previous_stage
   FROM (public.stage_history sh
     JOIN public.target_companies tc ON ((sh.target_company_id = tc.id)))
  WHERE (sh.changed_at IS NOT NULL);


ALTER VIEW public.deal_progression OWNER TO neondb_owner;

