--
-- Name: pipeline_summary; Type: VIEW; Schema: public; Owner: neondb_owner
--

CREATE VIEW public.pipeline_summary AS
 SELECT user_company_id,
    stage,
    count(*) AS deal_count,
    COALESCE(avg(EXTRACT(days FROM (now() - (stage_updated_at)::timestamp with time zone))), (0)::numeric) AS avg_days_in_stage,
    min(stage_updated_at) AS earliest_stage_entry,
    max(stage_updated_at) AS latest_stage_entry,
    round(avg(annual_revenue), 2) AS avg_revenue,
    sum(annual_revenue) AS total_revenue
   FROM public.target_companies tc
  WHERE (stage IS NOT NULL)
  GROUP BY user_company_id, stage;


ALTER VIEW public.pipeline_summary OWNER TO neondb_owner;

