--
-- Name: stage_1_progress; Type: VIEW; Schema: public; Owner: neondb_owner
--

CREATE VIEW public.stage_1_progress AS
 SELECT tc.id AS target_company_id,
    tc.company_name,
    count(cdr.id) AS total_requirements,
    count(
        CASE
            WHEN ((cdr.requirement_status)::text = ANY (ARRAY[('submitted'::character varying)::text, ('approved'::character varying)::text])) THEN 1
            ELSE NULL::integer
        END) AS completed_requirements,
    count(
        CASE
            WHEN ((cdr.requirement_status)::text = 'submitted'::text) THEN 1
            ELSE NULL::integer
        END) AS submitted_count,
    count(
        CASE
            WHEN ((cdr.requirement_status)::text = 'approved'::text) THEN 1
            ELSE NULL::integer
        END) AS approved_count,
    round((((count(
        CASE
            WHEN ((cdr.requirement_status)::text = ANY (ARRAY[('submitted'::character varying)::text, ('approved'::character varying)::text])) THEN 1
            ELSE NULL::integer
        END))::numeric / (count(cdr.id))::numeric) * (100)::numeric), 1) AS completion_percentage,
        CASE
            WHEN (count(
            CASE
                WHEN ((cdr.requirement_status)::text = ANY (ARRAY[('submitted'::character varying)::text, ('approved'::character varying)::text])) THEN 1
                ELSE NULL::integer
            END) = count(cdr.id)) THEN 'complete'::text
            WHEN (count(
            CASE
                WHEN ((cdr.requirement_status)::text = ANY (ARRAY[('submitted'::character varying)::text, ('approved'::character varying)::text])) THEN 1
                ELSE NULL::integer
            END) > 0) THEN 'in_progress'::text
            ELSE 'not_started'::text
        END AS overall_status,
    max(cdr.updated_at) AS last_activity
   FROM (public.target_companies tc
     LEFT JOIN public.company_document_requirements cdr ON (((tc.id = cdr.target_company_id) AND (cdr.collection_stage = 1))))
  GROUP BY tc.id, tc.company_name;


ALTER VIEW public.stage_1_progress OWNER TO neondb_owner;

